UPDATE indicators_lib.`lib_index_relation`
SET
    PERSONAL_FLAG = #{params.PERSONAL_FLAG},
    USER_ID = #{params.MODIFY_USERID},
    MODIFY_DATE = #{params.MODIFY_DATE}
WHERE INDEX_ID = #{params.INDEX_ID}
